// Derived from Barretenberg (https://github.com/AztecProtocol/aztec-packages, Copyright 2022 Aztec, Apache-2.0):
// the subrelations of RelationsLib in the Solidity verifier generated by bb v6.0.0. Changed: translated to Go.

package honk

import (
	"math/big"

	"github.com/consensys/gnark-crypto/ecc/bn254/fr"
)

var (
	negHalf                = frFromHex("183227397098d014dc2822db40c0ac2e9419f4243cdcb848a1f0fac9f8000000")
	grumpkinBNegated       = frU(17)
	limbSize               = func() fr.Element { var e fr.Element; e.SetBigInt(new(big.Int).Lsh(big.NewInt(1), 68)); return e }()
	sublimbShift           = frU(1 << 14)
	internalMatrixDiagonal = [4]fr.Element{frFromHex("10dc6e9c006ea38b04b1e03b4bd9490c0d03f98929ca1d7fb56821fd19d3b6e7"), frFromHex("0c28145b6a44df3e0149b3d0a30b3bb599df9756d4dd9b84a86b38cfb45a740b"), frFromHex("00544b8338791518b2c7645a50392798b21f75bb60e3596170067d00141cac15"), frFromHex("222c01175718386f2e2e82eb122789e352e105a3b8fa852613bc534433ee428b")}
)

// AccumulateRelationEvaluations evaluates the 31 subrelations at the sumcheck point and batches them with the alphas,
// as RelationsLib.accumulateRelationEvaluations of the bb v6.0.0 Solidity verifier.
func AccumulateRelationEvaluations(p *[NumberOfEntities]fr.Element, rp *RelationParameters, alphas *[NumberOfAlphas]fr.Element, pow fr.Element) fr.Element {
	var ev [NumberOfSubrelations]fr.Element

	arithmetic(p, &ev, pow)

	permutation(p, rp, &ev, pow)

	logDerivativeLookup(p, rp, &ev, pow)

	deltaRange(p, &ev, pow)

	elliptic(p, &ev, pow)

	memory(p, rp, &ev, pow)

	romLogup(p, rp, &ev, pow)

	nnf(p, &ev, pow)

	poseidonExternal(p, &ev, pow)

	poseidonInternal(p, &ev, pow)

	acc := ev[0]

	for i := 1; i < NumberOfSubrelations; i++ {
		acc = add(acc, mul(ev[i], alphas[i-1]))
	}

	return acc
}

func arithmetic(p *[NumberOfEntities]fr.Element, ev *[NumberOfSubrelations]fr.Element, ds fr.Element) {
	qArith := p[QArith]

	accum := mul3(sub(qArith, frU(3)), mul3(p[QM], p[WR], p[WL]), negHalf)

	accum = add(accum, add(add(add(add(mul(p[QL], p[WL]), mul(p[QR], p[WR])), mul(p[QO], p[WO])), mul(p[Q4], p[W4])), p[QC]))

	accum = add(accum, mul(sub(qArith, one), p[W4Shift]))

	accum = mul(mul(accum, qArith), ds)

	ev[6] = accum

	a2 := add(sub(add(p[WL], p[W4]), p[WLShift]), p[QM])

	a2 = mul(a2, sub(qArith, frU(2)))

	a2 = mul(a2, sub(qArith, one))

	a2 = mul(mul(a2, qArith), ds)

	ev[7] = a2
}

func permutation(p *[NumberOfEntities]fr.Element, rp *RelationParameters, ev *[NumberOfSubrelations]fr.Element, ds fr.Element) {
	term := func(w, s int) fr.Element {
		return add(add(p[w], mul(p[s], rp.Beta)), rp.Gamma)
	}

	num := mul(mul(mul(term(WL, Id1), term(WR, Id2)), term(WO, Id3)), term(W4, Id4))

	den := mul(mul(mul(term(WL, Sigma1), term(WR, Sigma2)), term(WO, Sigma3)), term(W4, Sigma4))

	acc := mul(add(p[ZPerm], p[LagrangeFirst]), num)

	acc = sub(acc, mul(add(p[ZPermShift], mul(p[LagrangeLast], rp.PublicInputsDelta)), den))

	ev[0] = mul(acc, ds)

	ev[1] = mul(mul(p[LagrangeLast], p[ZPermShift]), ds)

	ev[2] = mul(mul(p[LagrangeFirst], p[ZPerm]), ds)
}

func logDerivativeLookup(p *[NumberOfEntities]fr.Element, rp *RelationParameters, ev *[NumberOfSubrelations]fr.Element, ds fr.Element) {
	betaSqr := mul(rp.Beta, rp.Beta)

	tableTerm := add(add(add(add(p[Table1], rp.Gamma), mul(p[Table2], rp.Beta)), mul(p[Table3], betaSqr)), mul3(p[Table4], betaSqr, rp.Beta))

	d1 := add(add(p[WL], rp.Gamma), mul(p[QR], p[WLShift]))

	d2 := add(p[WR], mul(p[QM], p[WRShift]))

	d3 := add(p[WO], mul(p[QC], p[WOShift]))

	lookupTerm := add(add(add(d1, mul(d2, rp.Beta)), mul(d3, betaSqr)), mul3(p[QO], betaSqr, rp.Beta))

	lookupInverse := mul(p[LookupInverses], tableTerm)

	tableInverse := mul(p[LookupInverses], lookupTerm)

	inverseExistsXor := sub(add(p[LookupReadTags], p[QLookup]), mul(p[LookupReadTags], p[QLookup]))

	accNone := sub(mul3(lookupTerm, tableTerm, p[LookupInverses]), inverseExistsXor)

	ev[3] = mul(accNone, ds)

	ev[4] = sub(mul(p[QLookup], lookupInverse), mul(p[LookupReadCounts], tableInverse))

	readTag := p[LookupReadTags]

	ev[5] = mul(sub(mul(readTag, readTag), readTag), ds)
}

func deltaRange(p *[NumberOfEntities]fr.Element, ev *[NumberOfSubrelations]fr.Element, ds fr.Element) {
	deltas := [4]fr.Element{sub(p[WR], p[WL]), sub(p[WO], p[WR]), sub(p[W4], p[WO]), sub(p[WLShift], p[W4])}

	for i, d := range deltas {
		acc := mul(mul(mul(d, sub(d, one)), sub(d, frU(2))), sub(d, frU(3)))

		ev[8+i] = mul(mul(acc, p[QRange]), ds)
	}
}

func elliptic(p *[NumberOfEntities]fr.Element, ev *[NumberOfSubrelations]fr.Element, ds fr.Element) {
	x1, y1 := p[WR], p[WO]

	x2, y2 := p[WLShift], p[W4Shift]

	y3, x3 := p[WOShift], p[WRShift]

	qSign, qIsDouble := p[QL], p[QM]

	xDiff := sub(x2, x1)

	y1Sqr := mul(y1, y1)

	y2Sqr := mul(y2, y2)

	y1y2 := mul3(y1, y2, qSign)

	xAdd := mul3(add(add(x3, x2), x1), xDiff, xDiff)

	xAdd = add(add(sub(sub(xAdd, y2Sqr), y1Sqr), y1y2), y1y2)

	notDouble := sub(one, qIsDouble)

	ev[12] = mul(mul3(xAdd, ds, p[QElliptic]), notDouble)

	yAdd := add(mul(add(y1, y3), xDiff), mul(sub(x3, x1), sub(mul(y2, qSign), y1)))

	ev[13] = mul(mul3(yAdd, ds, p[QElliptic]), notDouble)

	xPow4 := mul(add(y1Sqr, grumpkinBNegated), x1)

	y1SqrMul4 := add(y1Sqr, y1Sqr)

	y1SqrMul4 = add(y1SqrMul4, y1SqrMul4)

	xDouble := sub(mul(add(add(x3, x1), x1), y1SqrMul4), mul(xPow4, frU(9)))

	ev[12] = add(ev[12], mul(mul3(xDouble, ds, p[QElliptic]), qIsDouble))

	x1SqrMul3 := mul(add(add(x1, x1), x1), x1)

	yDouble := sub(mul(x1SqrMul3, sub(x1, x3)), mul(add(y1, y1), add(y1, y3)))

	ev[13] = add(ev[13], mul(mul3(yDouble, ds, p[QElliptic]), qIsDouble))
}

func memory(p *[NumberOfEntities]fr.Element, rp *RelationParameters, ev *[NumberOfSubrelations]fr.Element, ds fr.Element) {
	eta := rp.Eta

	eta2 := mul(eta, eta)

	eta3 := mul(eta2, eta)

	minusOne := sub(fr.Element{}, one)

	recordCheck := add(add(add(mul(p[WO], eta3), mul(p[WR], eta2)), mul(p[WL], eta)), p[QC])

	partialRecordCheck := recordCheck

	recordCheck = sub(recordCheck, p[W4])

	indexDelta := sub(p[WLShift], p[WL])

	recordDelta := sub(p[W4Shift], p[W4])

	indexIsMonotonic := mul(indexDelta, sub(indexDelta, one))

	adjacentMatch := mul(add(mul(indexDelta, minusOne), one), recordDelta)

	qMemDs := mul(p[QMemory], ds)

	qlqr := mul(p[QL], p[QR])

	ev[15] = mul(mul(adjacentMatch, qlqr), qMemDs)

	ev[16] = mul(mul(indexIsMonotonic, qlqr), qMemDs)

	romConsistency := mul(recordCheck, qlqr)

	accessType := sub(p[W4], partialRecordCheck)

	accessCheck := mul(accessType, sub(accessType, one))

	nextAccessType := add(add(mul(p[WOShift], eta3), mul(p[WRShift], eta2)), mul(p[WLShift], eta))

	nextAccessType = sub(p[W4Shift], nextAccessType)

	valueDelta := sub(p[WOShift], p[WO])

	adjacentMatchRead := mul(mul(add(mul(indexDelta, minusOne), one), valueDelta), add(mul(nextAccessType, minusOne), one))

	nextAccessBoolean := sub(mul(nextAccessType, nextAccessType), nextAccessType)

	ev[17] = mul(mul(adjacentMatchRead, p[QO]), qMemDs)

	ev[18] = mul(mul(indexIsMonotonic, p[QO]), qMemDs)

	ev[19] = mul(mul(nextAccessBoolean, p[QO]), qMemDs)

	ramConsistency := mul(accessCheck, p[QO])

	timestampDelta := sub(p[WRShift], p[WR])

	ramTimestamp := sub(mul(add(mul(indexDelta, minusOne), one), timestampDelta), p[WO])

	identity := romConsistency

	identity = add(identity, mul(ramTimestamp, mul(p[Q4], p[QL])))

	identity = add(identity, mul(recordCheck, mul(p[QM], p[QL])))

	identity = add(identity, ramConsistency)

	ev[14] = mul(identity, qMemDs)
}

// romLogup is the ROM LogUp part of the memory relation that bb v6 adds (subrelations 20 and 21). Table rows have
// q_r (1 - q_l) = 1, read rows q_4 (1 - q_l) = 1, with wires (index, value, read count, inverse) and q_c the array id.
// Subrelation 21 is the LogUp sum, linearly dependent, so it is not scaled by the pow polynomial.
func romLogup(p *[NumberOfEntities]fr.Element, rp *RelationParameters, ev *[NumberOfSubrelations]fr.Element, ds fr.Element) {
	etaTwo := mul(rp.Eta, rp.Eta)

	qTable := mul(p[QR], sub(one, p[QL]))

	qRead := mul(p[Q4], sub(one, p[QL]))

	denom := add(add(add(rp.RomLogupGamma, p[WL]), mul(p[WR], rp.Eta)), mul(p[QC], etaTwo))

	ev[20] = mul3(add(qTable, qRead), sub(mul(p[W4], denom), one), mul(p[QMemory], ds))

	ev[21] = mul3(sub(qRead, mul(qTable, p[WO])), p[W4], p[QMemory])
}

func nnf(p *[NumberOfEntities]fr.Element, ev *[NumberOfSubrelations]fr.Element, ds fr.Element) {
	limbSubproduct := add(mul(p[WL], p[WRShift]), mul(p[WLShift], p[WR]))

	gate2 := sub(add(mul(p[WL], p[W4]), mul(p[WR], p[WO])), p[WOShift])

	gate2 = mul(gate2, limbSize)

	gate2 = sub(gate2, p[W4Shift])

	gate2 = add(gate2, limbSubproduct)

	gate2 = mul(gate2, p[Q4])

	limbSubproduct = mul(limbSubproduct, limbSize)

	limbSubproduct = add(limbSubproduct, mul(p[WLShift], p[WRShift]))

	gate1 := mul(sub(limbSubproduct, add(p[WO], p[W4])), p[QO])

	gate3 := mul(sub(add(limbSubproduct, p[W4]), add(p[WOShift], p[W4Shift])), p[QM])

	nnfIdentity := mul(add(add(gate1, gate2), gate3), p[QR])

	acc1 := mul(p[WRShift], sublimbShift)

	acc1 = mul(add(acc1, p[WLShift]), sublimbShift)

	acc1 = mul(add(acc1, p[WO]), sublimbShift)

	acc1 = mul(add(acc1, p[WR]), sublimbShift)

	acc1 = mul(sub(add(acc1, p[WL]), p[W4]), p[Q4])

	acc2 := mul(p[WOShift], sublimbShift)

	acc2 = mul(add(acc2, p[WRShift]), sublimbShift)

	acc2 = mul(add(acc2, p[WLShift]), sublimbShift)

	acc2 = mul(add(acc2, p[W4]), sublimbShift)

	acc2 = mul(sub(add(acc2, p[WO]), p[W4Shift]), p[QM])

	limbIdentity := mul(add(acc1, acc2), p[QO])

	ev[22] = mul(add(nnfIdentity, limbIdentity), mul(p[QNnf], ds))
}

func poseidonExternal(p *[NumberOfEntities]fr.Element, ev *[NumberOfSubrelations]fr.Element, ds fr.Element) {
	u1 := pow5(add(p[WL], p[QL]))

	u2 := pow5(add(p[WR], p[QR]))

	u3 := pow5(add(p[WO], p[QO]))

	u4 := pow5(add(p[W4], p[Q4]))

	t0 := add(u1, u2)

	t1 := add(u3, u4)

	t2 := add(add(u2, u2), t1)

	t3 := add(add(u4, u4), t0)

	v4 := add(t1, t1)

	v4 = add(add(v4, v4), t3)

	v2 := add(t0, t0)

	v2 = add(add(v2, v2), t2)

	v1 := add(t3, v2)

	v3 := add(t2, v4)

	q := mul(p[QPoseidon2External], ds)

	ev[23] = add(ev[23], mul(q, sub(v1, p[WLShift])))

	ev[24] = add(ev[24], mul(q, sub(v2, p[WRShift])))

	ev[25] = add(ev[25], mul(q, sub(v3, p[WOShift])))

	ev[26] = add(ev[26], mul(q, sub(v4, p[W4Shift])))
}

func poseidonInternal(p *[NumberOfEntities]fr.Element, ev *[NumberOfSubrelations]fr.Element, ds fr.Element) {
	u1 := pow5(add(p[WL], p[QL]))

	u2, u3, u4 := p[WR], p[WO], p[W4]

	uSum := add(add(add(u1, u2), u3), u4)

	q := mul(p[QPoseidon2Internal], ds)

	ev[27] = add(ev[27], mul(q, sub(add(mul(u1, internalMatrixDiagonal[0]), uSum), p[WLShift])))

	ev[28] = add(ev[28], mul(q, sub(add(mul(u2, internalMatrixDiagonal[1]), uSum), p[WRShift])))

	ev[29] = add(ev[29], mul(q, sub(add(mul(u3, internalMatrixDiagonal[2]), uSum), p[WOShift])))

	ev[30] = add(ev[30], mul(q, sub(add(mul(u4, internalMatrixDiagonal[3]), uSum), p[W4Shift])))
}
